package com.cryptostrategy.platform.leaderboard.internal;import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.model.BacktestResultId;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.experiment.api.ExperimentId;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class TopKProjectorTest{@Test void sortsScoreThenDrawdownThenFingerprintDeterministically(){ExperimentId x=new ExperimentId("00000000000000000000000030");RankingVersion v=new RankingVersion("ranking-v1");List<EvaluationResult> values=List.of(e("00000000000000000000000031",x,"0.8","0.2","b",v),e("00000000000000000000000032",x,"0.8","0.1","c",v),e("00000000000000000000000033",x,"0.8","0.1","a",v));var r=new TopKProjector().project(x,v,1,10,values);assertEquals(List.of("a","c","b"),r.entries().stream().map(e->e.evaluationFingerprint()).toList());assertEquals(List.of(1,2,3),r.entries().stream().map(e->e.rank()).toList());}@Test void rejectsCrossExperiment(){ExperimentId x=new ExperimentId("00000000000000000000000030");ExperimentId y=new ExperimentId("00000000000000000000000040");RankingVersion v=new RankingVersion("ranking-v1");assertThrows(IllegalArgumentException.class,()->new TopKProjector().project(x,v,1,10,List.of(e("00000000000000000000000031",y,"0.8","0.1","a",v))));}
 @Test void reproductionIsIndependentOfInputOrder(){ExperimentId x=new ExperimentId("00000000000000000000000030");RankingVersion v=new RankingVersion("ranking-v1");var a=e("00000000000000000000000031",x,"0.8","0.2","b",v);var b=e("00000000000000000000000032",x,"0.9","0.1","a",v);var projector=new TopKProjector();var first=projector.project(x,v,1,10,List.of(a,b));var second=projector.project(x,v,1,10,List.of(b,a));assertTrue(new LeaderboardReproductionVerifier().verify(first,second).isEmpty());}
 private EvaluationResult e(String id,ExperimentId experiment,String score,String dd,String fp,RankingVersion v){return new EvaluationResult(new EvaluationResultId(id),experiment,new BacktestResultId("00000000000000000000000050"),new MetricVersion("metrics-v1"),v,BigDecimal.ZERO,BigDecimal.ONE,new BigDecimal(dd),5,new BigDecimal(score),true,fp,Instant.parse("2026-01-01T00:00:00Z"));}}
